lemma Kripke.weakerThan_of_subset_FrameClass
  [sound₁ : Sound (Hilbert.ExtK Ax₁) C₁] [complete₂ : Complete (Hilbert.ExtK Ax₂) C₂]
  (h�� : C₂ ⊆ C₁)
  : (Hilbert.ExtK Ax₁) ≤ₛ (Hilbert.ExtK Ax₂) := by
  apply System.weakerThan_iff.mpr;
  intro φ hp;
  apply complete₂.complete;
  intro F hF;
  exact sound₁.sound hp $ h�� hF;

protected lemma axiomK : M ⊧ (Axioms.K φ ψ)  := by
  intro V;
  apply Satisfies.imp_def.mpr;
  intro hpq;
  apply Satisfies.imp_def.mpr;
  intro hp x Rxy;
  replace hpq := Satisfies.imp_def.mp $ hpq x Rxy;
  replace hp := hp x Rxy;
  exact hpq hp;

instance consistent : System.Consistent (Hilbert.KTB ℕ) := instConsistent_of_nonempty_frameclass (C := ReflexiveSymmetricFrameClass) $ by
  rw [ReflexiveSymmetricFrameClass.is_geach];
  exact MultiGeachConfluentFrameClass.nonempty;

